using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_SelfTarget", menuName = "Data/Battle/Logics/Enemy Action/Self Target")]
public class EnemyActionLogic_SelfTarget : EnemyActionLogic
{
	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.CastTarget(source, source);
		}
		else
		{
			battleAction.CastTargetAmount(source, actionAmount, source);
		}
	}
}
